package kr.yunseok.touchmacro;
import android.content.*;import android.graphics.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;

/** 실제 탭·입력·서비스 상태와 시스템 모션 설정의 연결을 검사합니다. */
@RunWith(AndroidJUnit4.class) public class PxeRedesignTest {
    PxeDesignReviewTest review=new PxeDesignReviewTest();GuidedFlowTest h=review.h;
    @Before public void boot()throws Exception{review.boot();h.main(()->{SetupFlow.finished(h.a);h.a.refreshSetup();});}
    @After public void end(){review.end();}
    View described(String value){return review.byDescription(h.a.findViewById(android.R.id.content),value);}
    TextView text(View root,String value){if(root instanceof TextView&&value.contentEquals(((TextView)root).getText()))return (TextView)root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){TextView out=text(group.getChildAt(i),value);if(out!=null)return out;}}return null;}
    EditText edit(View root){if(root instanceof EditText)return (EditText)root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){EditText out=edit(group.getChildAt(i));if(out!=null)return out;}}return null;}
    ScrollView scroll(View root){if(root instanceof ScrollView)return (ScrollView)root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){ScrollView out=scroll(group.getChildAt(i));if(out!=null)return out;}}return null;}
    @Test public void longKeywordScrollKeepsNavigationAndPrimaryReachable()throws Exception{
        String word="아주 긴 관심 키워드도 여러 줄로 자연스럽게 표시되어야 합니다";
        h.main(()->{WatchConfig p=WatchStore.load(h.a);p.rule.text=word;WatchStore.save(h.a,p);h.a.refreshSetup();});h.in.waitForIdleSync();
        h.main(()->{TextView title=text(h.a.findViewById(android.R.id.content),word);assertNotNull(title);assertTrue(title.getLineCount()>1);assertEquals(0,title.getLayout().getEllipsisCount(title.getLineCount()-1));assertTrue(h.bounds(described("설정")).height()>=Ui.dp(h.a,48));ScrollView sc=scroll(h.a.findViewById(android.R.id.content));sc.fullScroll(View.FOCUS_DOWN);});h.in.waitForIdleSync();
        h.waitFor(()->{final boolean[] ready={false};h.main(()->{ScrollView sc=scroll(h.a.findViewById(android.R.id.content));View body=privateView(h.a,"page");ready[0]=sc.getScrollY()==Math.max(0,sc.getChildAt(0).getHeight()-sc.getHeight())&&body.getAlpha()==1f&&body.getTranslationY()==0f;});return ready[0];},2000,"스크롤과 진입 전환이 완료되지 않았습니다");
        h.main(()->{TextView start=text(h.a.findViewById(android.R.id.content),"탐지 시작");Rect visible=new Rect();assertTrue(start.getGlobalVisibleRect(visible));assertEquals(start.getHeight(),visible.height());});h.screenshot("PXE14_긴문구_스크롤.png");review.tab("설정",3);review.tab("동작",1);review.tab("글자",0);review.tab("탐지",4);
    }

    int nativeControlTargets(android.view.accessibility.AccessibilityNodeInfo node){if(node==null)return 0;int count=0;String name=String.valueOf(node.getClassName());if((name.equals("android.widget.SeekBar")||name.equals("android.widget.CheckBox"))&&node.isVisibleToUser()){Rect bounds=new Rect();node.getBoundsInScreen(bounds);assertTrue(name+" 실제 터치 높이 "+bounds.height(),bounds.height()>=Ui.dp(h.a,48));count++;}for(int i=0;i<node.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo child=node.getChild(i);try{count+=nativeControlTargets(child);}finally{if(child!=null)child.recycle();}}return count;}
    @Test public void keyboardInputUsesRealSavePathAndLeavesNavigationAccessible()throws Exception{
        int scale=Ui.prefs(h.a).getInt("scale",100),opacity=Ui.prefs(h.a).getInt("opacity",95);boolean markers=Ui.prefs(h.a).getBoolean("markers",true),awake=Ui.prefs(h.a).getBoolean("keep_screen",true);
        review.tab("설정",3);h.main(()->described("화면 위 컨트롤 · 크기 · 투명도 · 번호 표시").performClick());h.in.waitForIdleSync();int count=0;for(android.view.accessibility.AccessibilityWindowInfo window:h.auto.getWindows()){android.view.accessibility.AccessibilityNodeInfo root=window.getRoot();try{count+=nativeControlTargets(root);}finally{if(root!=null)root.recycle();}}assertEquals(4,count);
        assertEquals(scale,Ui.prefs(h.a).getInt("scale",100));assertEquals(opacity,Ui.prefs(h.a).getInt("opacity",95));assertEquals(markers,Ui.prefs(h.a).getBoolean("markers",true));assertEquals(awake,Ui.prefs(h.a).getBoolean("keep_screen",true));h.click("터치 위치 번호 표시");assertEquals(!markers,Ui.prefs(h.a).getBoolean("markers",true));h.click("터치 위치 번호 표시");assertEquals(markers,Ui.prefs(h.a).getBoolean("markers",true));h.screenshot("PXE14_네이티브_설정_48dp.png");h.click("완료");review.tab("탐지",4);
        h.main(()->scroll(h.a.findViewById(android.R.id.content)).fullScroll(View.FOCUS_DOWN));h.in.waitForIdleSync();h.click("글자 · 매크로 설정");h.setAfter("탐지할 글자","새 관심 키워드");
        h.click("새 관심 키워드");h.waitFor(()->{for(android.view.accessibility.AccessibilityWindowInfo window:h.auto.getWindows())if(window.getType()==android.view.accessibility.AccessibilityWindowInfo.TYPE_INPUT_METHOD)return true;return false;},3000,"키보드가 표시되지 않았습니다");
        h.screenshot("PXE14_설정_입력.png");h.shell("input keyevent 4");h.click("저장");h.waitFor(()->WatchStore.load(h.a).rule.text.equals("새 관심 키워드"),3000,"입력값이 저장되지 않았습니다");review.tab("글자",0);
        h.main(()->{EditText field=edit(h.a.findViewById(android.R.id.content));assertNotNull(field);field.requestFocus();((InputMethodManager)h.a.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(field,InputMethodManager.SHOW_IMPLICIT);});
        h.waitFor(()->{for(android.view.accessibility.AccessibilityWindowInfo window:h.auto.getWindows())if(window.getType()==android.view.accessibility.AccessibilityWindowInfo.TYPE_INPUT_METHOD)return true;return false;},3000,"글자 탭의 키보드가 표시되지 않았습니다");
        h.main(()->{Rect visible=new Rect(),navVisible=new Rect();h.a.getWindow().getDecorView().getWindowVisibleDisplayFrame(visible);View nav=described("탐지");assertTrue(nav.getGlobalVisibleRect(navVisible));assertEquals(h.bounds(nav),navVisible);assertTrue("키보드 위의 탐색 영역",navVisible.bottom<=visible.bottom);});h.screenshot("PXE14_글자_키보드_탐색.png");review.tab("탐지",4);
    }
    @Test public void dockReadsLiveServiceWithoutReplacingViewsAndCleansCallbacks()throws Exception{
        final View[] before={null};h.main(()->{Macro m=new Macro();m.startDelay=0;m.maxMinutes=1;Step wait=new Step("WAIT");wait.duration=4000;m.steps.add(wait);h.svc.start(m);h.svc.togglePause();h.a.refreshSetup();before[0]=described("실행 상태");});h.waitFor(()->h.svc.running,2000,"실행이 시작되지 않았습니다");SystemClock.sleep(600);
        h.main(()->{assertSame(before[0],described("실행 상태"));assertEquals(h.svc.progressText(),((TextView)before[0]).getText().toString());assertTrue(((TextView)described("실행 시간")).getText().toString().contains("전체 경과"));h.svc.stop();});SystemClock.sleep(400);
        h.main(()->{assertSame(before[0],described("실행 상태"));assertEquals(h.svc.progressText(),((TextView)before[0]).getText().toString());h.a.finish();});h.in.waitForIdleSync();
        java.lang.reflect.Field handler=MainActivity.class.getDeclaredField("connectionUi"),callback=MainActivity.class.getDeclaredField("watchConnection");handler.setAccessible(true);callback.setAccessible(true);assertFalse(((Handler)handler.get(h.a)).hasCallbacks((Runnable)callback.get(h.a)));
    }
    View privateView(Object owner,String name){try{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return (View)f.get(owner);}catch(Exception e){throw new RuntimeException(e);}}
    View marker(){try{java.lang.reflect.Field f=FloatingController.class.getDeclaredField("markers");f.setAccessible(true);java.util.List<?> views=(java.util.List<?>)f.get(h.svc.controller());assertFalse(views.isEmpty());return (View)views.get(0);}catch(Exception e){throw new RuntimeException(e);}}
    void markerCenter(double tolerance){View marker=marker();Rect bounds=h.bounds(marker);Step saved=Store.load(h.a).steps.get(0);int[] size=h.svc.size();assertEquals("표시와 저장 X 중심",saved.x*size[0]/100,bounds.exactCenterX(),tolerance);assertEquals("표시와 저장 Y 중심",saved.y*size[1]/100,bounds.exactCenterY(),tolerance);}
    void targets(View root){if(root instanceof Button||root instanceof ImageButton){assertTrue("터치 너비: "+root.getContentDescription(),root.getWidth()>=Ui.dp(h.a,48));assertTrue("터치 높이: "+root.getContentDescription(),root.getHeight()>=Ui.dp(h.a,48));}if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++)targets(group.getChildAt(i));}}
    @Test public void nativeMotionHasDifferentFramesAndHonorsSystemDisabled()throws Exception{
        h.main(()->{Ui.prefs(h.a).edit().putInt("scale",100).putBoolean("markers",true).commit();Macro m=new Macro();Step tap=new Step("TAP");tap.x=50;tap.y=50;m.steps.add(tap);Store.save(h.a,m);h.svc.controller().show();});h.in.waitForIdleSync();h.main(()->{View panel=privateView(h.svc.controller(),"panel");targets(panel);View logo=review.byDescription(panel,"PXE 컨트롤 펼치기 · 길게 눌러 정지");assertNotNull(logo);logo.performClick();});h.in.waitForIdleSync();h.main(()->{targets(privateView(h.svc.controller(),"panel"));targets(marker());markerCenter(.51);});h.screenshot("PXE14_제어창_펼침.png");final Rect[] before={null};h.main(()->before[0]=h.bounds(marker()));h.drag(before[0].exactCenterX(),before[0].exactCenterY(),before[0].exactCenterX()+100,before[0].exactCenterY()-80);h.in.waitForIdleSync();h.main(()->{markerCenter(.000001);Step saved=Store.load(h.a).steps.get(0);assertTrue(saved.x>50);assertTrue(saved.y<50);});h.screenshot("PXE14_번호점_이동.png");h.main(()->h.svc.controller().close());
        final SetupCoach[] coach={null};h.main(()->{coach[0]=new SetupCoach(h.svc);coach[0].show("기본 크기 안내 버튼 검사","영역 그리기",()->{},()->{});});h.in.waitForIdleSync();h.main(()->targets(privateView(coach[0],"view")));h.main(()->coach[0].close());
        float original=Settings.Global.getFloat(h.a.getContentResolver(),Settings.Global.ANIMATOR_DURATION_SCALE,1f);final View[] target={null};final float[] alpha={-1,-1};
        try{
            h.shell("settings put global animator_duration_scale 1");h.waitFor(()->android.animation.ValueAnimator.areAnimatorsEnabled(),3000,"시스템 모션이 활성화되지 않았습니다");
            h.main(()->{described("동작").performClick();target[0]=privateView(h.a,"page");alpha[0]=target[0].getAlpha();});SystemClock.sleep(70);h.main(()->alpha[1]=target[0].getAlpha());assertTrue("서로 다른 전환 프레임",alpha[1]>alpha[0]&&alpha[1]<1f);SystemClock.sleep(180);h.main(()->assertEquals(1f,target[0].getAlpha(),.001f));
            h.shell("settings put global animator_duration_scale 0");h.waitFor(()->!android.animation.ValueAnimator.areAnimatorsEnabled(),3000,"시스템 모션 꺼짐이 적용되지 않았습니다");h.main(()->{described("설정").performClick();target[0]=privateView(h.a,"page");assertEquals(1f,target[0].getAlpha(),.001f);assertEquals(0f,target[0].getTranslationY(),.001f);});h.screenshot("PXE14_모션꺼짐.png");
        }finally{h.shell("settings put global animator_duration_scale "+original);}
    }
}
